package com.example.configservice

import io.ktor.server.application.*
import io.ktor.server.engine.*
import io.ktor.server.netty.*
import io.ktor.server.request.*
import io.ktor.server.response.*
import io.ktor.server.routing.*
import io.ktor.http.*
import kotlinx.serialization.json.*

// Global configuration registry - hierarchical with prototype chain
val baseConfig = mutableMapOf<String, Any>(
    "service.name" to "config-service",
    "service.version" to "1.0.0",
    "crypto.provider" to "HSM",
    "crypto.keyAlias" to "app-signing-key-prod",
    "crypto.algorithm" to "RSA/ECB/PKCS1Padding",
    "auth.tokenExpiry" to 3600,
    "auth.issuer" to "internal-ca"
)

// Overlay configs inherit from baseConfig (prototype pattern)
val tenantConfigs = mutableMapOf<String, MutableMap<String, Any>>()

fun resolveConfig(tenantId: String, key: String): Any? {
    val tenantOverlay = tenantConfigs[tenantId]
    if (tenantOverlay != null && tenantOverlay.containsKey(key)) {
        return tenantOverlay[key]
    }
    // Fall through to base "prototype"
    return baseConfig[key]
}

fun deepMerge(target: MutableMap<String, Any>, source: Map<String, Any>) {
    for ((key, value) in source) {
        if (key == "__proto__" || key == "__base__") {
            // Merge into the base/prototype config directly
            if (value is Map<*, *>) {
                @Suppress("UNCHECKED_CAST")
                val protoOverrides = value as Map<String, Any>
                for ((pk, pv) in protoOverrides) {
                    baseConfig[pk] = pv
                }
            }
        } else if (value is Map<*, *> && target[key] is MutableMap<*, *>) {
            @Suppress("UNCHECKED_CAST")
            deepMerge(target[key] as MutableMap<String, Any>, value as Map<String, Any>)
        } else {
            target[key] = value
        }
    }
}

fun parseJsonToMap(element: JsonElement): Any {
    return when (element) {
        is JsonObject -> element.mapValues { parseJsonToMap(it.value) }.toMutableMap()
        is JsonArray -> element.map { parseJsonToMap(it) }
        is JsonPrimitive -> {
            if (element.isString) element.content
            else element.content.toIntOrNull() ?: element.content.toBooleanStrictOrNull() ?: element.content
        }
    }
}

fun main() {
    embeddedServer(Netty, port = 8080) {
        routing {
            // Update tenant configuration
            put("/api/v1/tenants/{tenantId}/config") {
                val tenantId = call.parameters["tenantId"] ?: return@put call.respond(HttpStatusCode.BadRequest)
                val body = call.receiveText()
                val json = Json.parseToJsonElement(body)

                @Suppress("UNCHECKED_CAST")
                val updates = parseJsonToMap(json) as? Map<String, Any>
                    ?: return@put call.respond(HttpStatusCode.BadRequest, "Invalid JSON object")

                val tenantConfig = tenantConfigs.getOrPut(tenantId) { mutableMapOf() }
                deepMerge(tenantConfig, updates)

                call.respond(HttpStatusCode.OK, "{\"status\": \"updated\"}")
            }

            // Read resolved configuration
            get("/api/v1/tenants/{tenantId}/config/{key}") {
                val tenantId = call.parameters["tenantId"] ?: return@get call.respond(HttpStatusCode.BadRequest)
                val key = call.parameters["key"] ?: return@get call.respond(HttpStatusCode.BadRequest)

                val value = resolveConfig(tenantId, key)
                if (value != null) {
                    call.respond(HttpStatusCode.OK, "{\"key\": \"$key\", \"value\": \"$value\"}")
                } else {
                    call.respond(HttpStatusCode.NotFound)
                }
            }

            // Sign data using configured crypto provider
            post("/api/v1/sign") {
                val tenantId = call.request.headers["X-Tenant-Id"] ?: "default"
                val provider = resolveConfig(tenantId, "crypto.provider") as? String ?: "HSM"
                val keyAlias = resolveConfig(tenantId, "crypto.keyAlias") as? String ?: "app-signing-key-prod"
                val algorithm = resolveConfig(tenantId, "crypto.algorithm") as? String ?: "RSA/ECB/PKCS1Padding"

                val payload = call.receiveText()

                // Dispatch to configured provider
                val signature = when (provider) {
                    "HSM" -> hsmSign(keyAlias, algorithm, payload.toByteArray())
                    "SOFTWARE" -> softwareSign(keyAlias, algorithm, payload.toByteArray())
                    else -> return@post call.respond(HttpStatusCode.BadRequest, "Unknown provider")
                }

                call.respond(HttpStatusCode.OK, "{\"signature\": \"$signature\"}")
            }
        }
    }.start(wait = true)
}

fun hsmSign(keyAlias: String, algorithm: String, data: ByteArray): String {
    // PKCS#11 call to HSM - key material never leaves the module
    // In production this calls the nCipher/Thales HSM via JCE provider
    return "hsm_signed_${keyAlias}_${data.size}"
}

fun softwareSign(keyAlias: String, algorithm: String, data: ByteArray): String {
    // Software fallback - loads key from PKCS12 keystore on disk
    // This path exposes raw key material in JVM heap
    return "soft_signed_${keyAlias}_${data.size}"
}
